pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: remaining space after placement.
    let mut score = post_residual as f64;

    // Reward perfect fits heavily.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward being the last viable bin for this item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize having many open bins (encourage closing them).
    score += open_bins_count as f64 * 1.0;

    // Prefer bins whose residual after placement is close to the mean residual
    // (i.e., avoid creating bins with unusually high leftover space).
    score += (mean_residual - post_residual as f64) * 0.5;

    // Lookahead: penalize bins that will leave insufficient space for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Dynamic time horizon: if we are late in the stream, penalize residual space more
    // to finish bins quickly.
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * (1.0 - progress) * 0.5;

    // New‑bin candidate: if the bin is still empty, slightly reward opening a fresh bin
    // when many bins are already open (to reduce fragmentation).
    if bin_residual == bin_capacity {
        score -= open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the post‑residual space: lower is better
    let mut score = post_residual as f64;

    // 1. Dead‑space penalty: if the gap left after placing this item cannot
    // accommodate the next item, we add a proportional penalty.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.2;
    }

    // 2. Balance penalty: reward bins whose residual is close to the mean.
    // The closer to the mean, the less we subtract.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score -= residual_diff * 0.5;

    // 3. Open‑bin pressure: the more open bins we have, the higher the cost
    // of keeping another partially filled bin.
    score += open_bins_count as f64 * 0.05;

    // 4. Singleton fit bonus: if this is the only bin that can accept the item,
    // we give it a small advantage.
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // 5. End‑of‑stream tightening: as we approach the last item we prefer
    // to finish bins, so we add a small penalty proportional to the remaining
    // fraction of the stream and the open‑bin count.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * open_bins_count as f64 * 0.02;

    // 6. Optional capacity scaling: penalize bins that are almost empty
    // relative to capacity, encouraging tighter packing early in the stream.
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_ratio) * 0.3;

    score
}

