pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // baseline: remaining space after placement
    let mut score = post_residual as f64;

    // progress factor: more aggressive as we near the end
    let progress = step_index as f64 / total_items as f64;
    let late_factor = 1.0 + progress; // ranges from 1 to 2

    // Only one bin can fit the item – strongly reward this bin
    if fitting_bins_count == 1 {
        score -= 20.0 * late_factor;
    }

    // Opening a new bin when other bins exist and the average residual is large is bad
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 30.0;
        }
    }

    // If the mean residual is smaller than the current item, using an existing bin is risky
    if mean_residual < item_size as f64 {
        score += 15.0;
    }

    // Very small post‑residual may create unusable dead space
    if post_residual < 5 {
        score += 5.0;
    }

    // Penalize bins that will leave insufficient space for the next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5 * late_factor;
    }

    // Slight penalty for bins whose residual deviates from the mean
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.01;

    // Reward bins with a larger residual than the mean (they can accommodate future items)
    if bin_residual as f64 > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.02 * late_factor;
    }

    // Too many open bins – encourage consolidation
    if open_bins_count > 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Progress of the stream (0.0 at start, 1.0 at end)
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Residual ratios for reference
    let residual_ratio = bin_residual as f64 / bin_capacity as f64;
    let mean_ratio = mean_residual / bin_capacity as f64;
    let next_ratio = if next_item_size > 0 {
        next_item_size as f64 / bin_capacity as f64
    } else {
        0.0
    };

    // Base score: the remaining space after placing the item
    let mut score = post_residual as f64;

    // Penalise large residuals (want bins close to full)
    score += 0.5 * residual_ratio * bin_capacity as f64;

    // Penalise deviation from the mean residual (reduce variance)
    let diff_to_mean = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * diff_to_mean;

    // Look‑ahead: avoid leaving space smaller than the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Large penalty for future incompatibility
            score += 2000.0
                * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        } else {
            // Small reward if we can fit the next item comfortably
            score -= 5.0
                * ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Penalise having many open bins (fragmentation cost)
    score += 3.0 * (open_bins_count as f64);

    // Prefer tighter bins as the stream progresses
    score -= 15.0 * progress;

    // If this is the sole bin that can fit the item, favour using it
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New‑bin candidate: penalise opening a new bin when other open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 100.0;
    }

    score
}
